package factory_dispatch_coordinator.Factory_Dispatch_Coordinator

import org.sireum._
import art._
import factory_dispatch_coordinator._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait Confirmation_Determiner_Api {
  def id: Art.BridgeId
  def confirmation_context_Id : Art.PortId
  def shipping_confirmation_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var shipping_confirmation: Factory_Dispatch_Coordinator.Shipping_Confirmation = $

  def put_shipping_confirmation(value : Factory_Dispatch_Coordinator.Shipping_Confirmation) : Unit = {
    Contract(
      Modifies(shipping_confirmation),
      Ensures(
        shipping_confirmation == value
      )
    )
    Spec {
      shipping_confirmation = value
    }

    Art.putValue(shipping_confirmation_Id, Factory_Dispatch_Coordinator.Shipping_Confirmation_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class Confirmation_Determiner_Initialization_Api (
  val id: Art.BridgeId,
  val confirmation_context_Id : Art.PortId,
  val shipping_confirmation_Id : Art.PortId) extends Confirmation_Determiner_Api

@datatype class Confirmation_Determiner_Operational_Api (
  val id: Art.BridgeId,
  val confirmation_context_Id : Art.PortId,
  val shipping_confirmation_Id : Art.PortId) extends Confirmation_Determiner_Api {

  // Logika spec var representing port state for incoming data port
  @spec var confirmation_context: Factory_Dispatch_Coordinator.Confirmation_Context = $

  def get_confirmation_context() : Option[Factory_Dispatch_Coordinator.Confirmation_Context] = {
    Contract(
      Ensures(
        Res == Some(confirmation_context)
      )
    )
    val value : Option[Factory_Dispatch_Coordinator.Confirmation_Context] = Art.getValue(confirmation_context_Id) match {
      case Some(Factory_Dispatch_Coordinator.Confirmation_Context_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port confirmation_context.  Expecting 'Factory_Dispatch_Coordinator.Confirmation_Context_Payload' but received ${v}")
        None[Factory_Dispatch_Coordinator.Confirmation_Context]()
      case _ => None[Factory_Dispatch_Coordinator.Confirmation_Context]()
    }
    return value
  }
}
